screenPanels.initJs:
function(container, apiUrl, tables) {
  const errorTable = tables[0];
  const logTable = tables[1];
  let currentSelectedError = null;

  // ===== 1. KPI 計算関数 =====
  function updateKPIs(errors) {
    const today = new Date().toISOString().split('T')[0];
    const totalCount = errors.length;
    const pendingCount = errors.filter(e => e.ステータス !== '解決済み').length;
    const criticalCount = errors.filter(e => e.重要度 === 'CRITICAL').length;
    const todayCount = errors.filter(e => e.作成日時 && e.作成日時.startsWith(today)).length;

    container.querySelector('[data-testid="kpi-total-errors"]').textContent = totalCount;
    container.querySelector('[data-testid="kpi-pending-errors"]').textContent = pendingCount;
    container.querySelector('[data-testid="kpi-critical-errors"]').textContent = criticalCount;
    container.querySelector('[data-testid="kpi-today-errors"]').textContent = todayCount;
  }

  // ===== 2. グラフ描画関数 =====
  function drawCharts(errors) {
    // 重要度別分布（円グラフ）
    const severityMap = {};
    errors.forEach(e => {
      const sev = e.重要度 || 'INFO';
      severityMap[sev] = (severityMap[sev] || 0) + 1;
    });
    const severityLabels = Object.keys(severityMap);
    const severityData = Object.values(severityMap);
    const severityColors = ['#d32f2f', '#ff6a00', '#fbc02d', '#4caf50'];

    if (window.Chart) {
      const ctxSev = document.getElementById('chart-severity').getContext('2d');
      if (window.chartSeverity) window.chartSeverity.destroy();
      window.chartSeverity = new window.Chart(ctxSev, {
        type: 'doughnut',
        data: {
          labels: severityLabels,
          datasets: [{
            data: severityData,
            backgroundColor: severityColors.slice(0, severityLabels.length),
            borderColor: 'rgba(0,0,0,0.3)',
            borderWidth: 1
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: { legend: { position: 'bottom', labels: { font: { size: 11 }, color: '#9fb0d1' } } }
        }
      });
    }

    // ステータス別件数（棒グラフ）
    const statusMap = {};
    errors.forEach(e => {
      const st = e.ステータス || '未対応';
      statusMap[st] = (statusMap[st] || 0) + 1;
    });
    const statusLabels = Object.keys(statusMap);
    const statusData = Object.values(statusMap);

    if (window.Chart) {
      const ctxSt = document.getElementById('chart-status').getContext('2d');
      if (window.chartStatus) window.chartStatus.destroy();
      window.chartStatus = new window.Chart(ctxSt, {
        type: 'bar',
        data: {
          labels: statusLabels,
          datasets: [{
            label: '件数',
            data: statusData,
            backgroundColor: '#4a90e2',
            borderColor: '#2e5c8a',
            borderWidth: 1
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          indexAxis: 'y',
          plugins: { legend: { display: false } },
          scales: { x: { ticks: { color: '#9fb0d1' } }, y: { ticks: { color: '#9fb0d1' } } }
        }
      });
    }
  }

  // ===== 3. エラー一覧再描画 =====
  function renderErrors(errors) {
    const tbody = container.querySelector('#error-tbody');
    if (errors.length === 0) {
      tbody.innerHTML = '<tr><td colspan="6" style="padding:20px; text-align:center; color:var(--text-muted);">エラーがありません</td></tr>';
      return;
    }
    tbody.innerHTML = errors.map(e => {
      const severityColor = e.重要度 === 'CRITICAL' ? '#d32f2f' : e.重要度 === 'ERROR' ? '#ff6a00' : '#fbc02d';
      return `
        <tr data-id="${e.エラーログID || e.id}" style="border-bottom:1px solid rgba(255,255,255,0.08); cursor:pointer; transition:background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.05)'" onmouseout="this.style.background=''">
          <td style="padding:8px; color:var(--text-muted); font-family:monospace; font-size:10px;">${(e.エラーログID || e.id || '').substring(0, 8)}</td>
          <td style="padding:8px; color:var(--text);">${e.受注番号 || '-'}</td>
          <td style="padding:8px;"><span style="display:inline-block; padding:2px 6px; border-radius:3px; background:${severityColor}; color:#fff; font-size:10px; font-weight:600;">${e.重要度 || 'INFO'}</span></td>
          <td style="padding:8px; color:var(--text); font-family:monospace; font-size:10px;">${e.エラーコード || '-'}</td>
          <td style="padding:8px; color:var(--text);">${e.ステータス || '未対応'}</td>
          <td style="padding:8px; color:var(--text-muted); font-size:11px;">${e.作成日時 ? e.作成日時.substring(0, 16) : '-'}</td>
        </tr>
      `;
    }).join('');
  }

  // ===== 4. 詳細パネル表示 =====
  function showDetail(error) {
    currentSelectedError = error;
    container.querySelector('#detail-empty').style.display = 'none';
    container.querySelector('#detail-panel').style.display = 'block';
    container.querySelector('#detail-error-id').textContent = error.エラーログID || error.id || '';
    container.querySelector('#detail-message').textContent = error.エラーメッセージ || '';
    container.querySelector('#detail-detail').textContent = error.エラー詳細 || '';
    container.querySelector('#detail-classification').value = error.エラー分類 || '';
    container.querySelector('#detail-assignee').value = error.責任者 || '';
    container.querySelector('#detail-status').value = error.ステータス || '未対応';
    container.querySelector('#detail-comment').value = error.対応コメント || '';
  }

  // ===== 5. ログタイムライン描画 =====
  function renderLogs(logs) {
    const timeline = container.querySelector('#log-timeline');
    if (!logs || logs.length === 0) {
      timeline.innerHTML = '<div style="color:var(--text-muted); text-align:center; padding:10px 0;">ログなし</div>';
      return;
    }
    timeline.innerHTML = logs.slice(0, 5).map(log => `
      <div style="padding:8px 0; border-bottom:1px solid rgba(255,255,255,0.08); font-size:10px;">
        <div style="color:var(--text-muted);">${log.作成日時 ? log.作成日時.substring(0, 16) : ''}</div>
        <div style="color:var(--text); margin-top:2px;">${log.エラーメッセージ || log.内容 || ''}</div>
      </div>
    `).join('');
  }

  // ===== 6. 初期データ読み込み =====
  const initialErrors = errorTable.records || [];
  const initialLogs = logTable.records || [];
  updateKPIs(initialErrors);
  drawCharts(initialErrors);
  renderErrors(initialErrors);
  renderLogs(initialLogs);

  // ===== 7. 検索ボタン =====
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const orderNo = container.querySelector('#filter-order-no').value.trim();
    const severity = container.querySelector('#filter-severity').value;
    const status = container.querySelector('#filter-status').value;

    let filtered = initialErrors;
    if (orderNo) filtered = filtered.filter(e => (e.受注番号 || '').includes(orderNo));
    if (severity) filtered = filtered.filter(e => e.重要度 === severity);
    if (status) filtered = filtered.filter(e => e.ステータス === status);

    updateKPIs(filtered);
    drawCharts(filtered);
    renderErrors(filtered);
  });

  // ===== 8. バリデーション実行ボタン =====
  container.querySelector('#btn-validate').addEventListener('click', async () => {
    alert('バリデーション実行を開始します。\n（実装: 基幹システム連携実行画面へ遷移）');
    window.showScreen('scr-1781408509581');
  });

  // ===== 9. エラー行クリック（詳細表示） =====
  container.addEventListener('click', e => {
    const row = e.target.closest('tr[data-id]');
    if (row && row.querySelector('td')) {
      const errorId = row.dataset.id;
      const error = initialErrors.find(err => (err.エラーログID || err.id) === errorId);
      if (error) showDetail(error);
    }
  });

  // ===== 10. エラー更新ボタン =====
  container.querySelector('#btn-update-error').addEventListener('click', async () => {
    if (!currentSelectedError) return;
    const updated = {
      ...currentSelectedError,
      エラー分類: container.querySelector('#detail-classification').value,
      責任者: container.querySelector('#detail-assignee').value,
      ステータス: container.querySelector('#detail-status').value,
      対応コメント: container.querySelector('#detail-comment').value
    };
    const result = await window.aivicApi.update(0, currentSelectedError.エラーログID || currentSelectedError.id, updated);
    if (result) {
      alert('エラー情報を更新しました');
      const idx = initialErrors.findIndex(e => (e.エラーログID || e.id) === (currentSelectedError.エラーログID || currentSelectedError.id));
      if (idx >= 0) initialErrors[idx] = updated;
      updateKPIs(initialErrors);
      renderErrors(initialErrors);
      showDetail(updated);
    }
  });

  // ===== 11. 通知送信ボタン =====
  container.querySelector('#btn-notify').addEventListener('click', async () => {
    if (!currentSelectedError) return;
    const assignee = container.querySelector('#detail-assignee').value;
    if (!assignee) {
      alert('責任者を選択してください');
      return;
    }
    alert(`${assignee}に通知を送信しました。`);
    // 実装: 通知履歴テーブルに記録
  });

  // ===== 12. ルール詳細リンク =====
  container.querySelector('#detail-rule-link').addEventListener('click', () => {
    alert('バリデーションルール詳細を表示します。\n（実装: ルール管理画面へ遷移）');
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#error-log-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const detailEmpty = container.querySelector("#detail-empty");
  let allRows = [];
  let selectedRow = null;

  // 1. 再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="height: 40px;"><td colspan="5" style="padding: 12px; text-align: center; color: var(--text-muted);">該当するログはありません</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => {
      const severity = r.重要度 || r.severity || 'INFO';
      const severityColor = severity === 'CRITICAL' ? '#ff4444' : severity === 'ERROR' ? '#ff6a00' : severity === 'WARNING' ? '#ffa500' : '#4a9eff';
      return `<tr data-id="${r.エラーログID || r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer; transition: background 0.2s;">
        <td style="padding: 8px 10px; color: var(--text); font-size: 11px; word-break: break-all;">${(r.エラーログID || r.id || '').substring(0, 8)}</td>
        <td style="padding: 8px 10px; color: var(--text); font-size: 11px; word-break: break-all;">${(r.受注データID || r.orderId || '').substring(0, 8)}</td>
        <td style="padding: 8px 10px; color: var(--text-muted); font-size: 11px;">${r.作成日時 ? new Date(r.作成日時).toLocaleString('ja-JP') : '—'}</td>
        <td style="padding: 8px 10px; color: #ff6a00; font-weight: 600; font-size: 11px;">${r.エラーコード || r.errorCode || '—'}</td>
        <td style="padding: 8px 10px; color: var(--text); font-size: 11px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${r.エラーメッセージ || r.errorMessage || '—'}</td>
      </tr>`;
    }).join("");
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    allRows = rows || [];
    renderRows(allRows);
  });

  // 3. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", () => {
    const dateFrom = container.querySelector("#filter-date-from").value;
    const dateTo = container.querySelector("#filter-date-to").value;
    const errorCode = container.querySelector("#filter-error-code").value.toUpperCase();
    const orderId = container.querySelector("#filter-order-id").value;
    const channel = container.querySelector("#filter-channel").value;
    const status = container.querySelector("#filter-status").value;

    const filtered = allRows.filter(r => {
      const createdAt = r.作成日時 ? new Date(r.作成日時) : null;
      const fromDate = dateFrom ? new Date(dateFrom) : null;
      const toDate = dateTo ? new Date(dateTo) : null;

      if (fromDate && createdAt && createdAt < fromDate) return false;
      if (toDate && createdAt && createdAt > toDate) return false;
      if (errorCode && !(r.エラーコード || r.errorCode || '').toUpperCase().includes(errorCode)) return false;
      if (orderId && !(r.受注データID || r.orderId || '').includes(orderId)) return false;
      if (channel && (r.チャネル || r.channel) !== channel) return false;
      if (status && (r.ステータス || r.status) !== status) return false;
      return true;
    });

    renderRows(filtered);
  });

  // 4. CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", () => {
    if (!allRows || allRows.length === 0) {
      alert("エクスポート対象のデータがありません");
      return;
    }
    const headers = ["ログID", "受注ID", "発生日時", "エラーコード", "エラーメッセージ", "エラー種別", "重要度", "ステータス"];
    const csv = [headers.map(h => `"${h}"`).join(",")];
    allRows.forEach(r => {
      const row = [
        r.エラーログID || r.id || '',
        r.受注データID || r.orderId || '',
        r.作成日時 ? new Date(r.作成日時).toLocaleString('ja-JP') : '',
        r.エラーコード || r.errorCode || '',
        (r.エラーメッセージ || r.errorMessage || '').replace(/"/g, '""'),
        r.エラー種別 || r.errorType || '',
        r.重要度 || r.severity || '',
        r.ステータス || r.status || ''
      ];
      csv.push(row.map(v => `"${v}"`).join(","));
    });
    const bom = '\uFEFF';
    const blob = new Blob([bom + csv.join("\n")], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `error-logs-${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 5. 行クリックで詳細表示
  container.addEventListener("click", e => {
    const tr = e.target.closest("tbody tr");
    if (!tr) return;

    const id = tr.dataset.id;
    const row = allRows.find(r => (r.エラーログID || r.id) === id);
    if (!row) return;

    selectedRow = row;
    detailEmpty.style.display = "none";
    detailPanel.style.display = "block";

    // 詳細パネルに値を設定
    container.querySelector("#detail-log-id").textContent = row.エラーログID || row.id || '—';
    container.querySelector("#detail-order-id").textContent = row.受注データID || row.orderId || '—';
    container.querySelector("#detail-error-code").textContent = `エラーコード: ${row.エラーコード || row.errorCode || '—'}`;
    container.querySelector("#detail-error-message").textContent = row.エラーメッセージ || row.errorMessage || '—';
    container.querySelector("#detail-created-at").textContent = row.作成日時 ? new Date(row.作成日時).toLocaleString('ja-JP') : '—';
    container.querySelector("#detail-status").textContent = row.ステータス || row.status || '—';
    container.querySelector("#detail-error-type").textContent = row.エラー種別 || row.errorType || '—';

    const severity = row.重要度 || row.severity || 'INFO';
    const severityColor = severity === 'CRITICAL' ? '#ff4444' : severity === 'ERROR' ? '#ff6a00' : severity === 'WARNING' ? '#ffa500' : '#4a9eff';
    const badge = container.querySelector("#detail-severity-badge");
    badge.textContent = severity;
    badge.style.background = severity === 'CRITICAL' ? 'rgba(255,68,68,0.2)' : severity === 'ERROR' ? 'rgba(255,106,0,0.2)' : severity === 'WARNING' ? 'rgba(255,165,0,0.2)' : 'rgba(74,158,255,0.2)';
    badge.style.color = severityColor;

    container.querySelector("#detail-error-detail").textContent = row.エラー詳細 || row.errorDetail || '—';
    container.querySelector("#detail-comment").value = row.対応コメント || row.comment || '';

    // ハイライト
    document.querySelectorAll("tbody tr").forEach(t => t.style.background = "");
    tr.style.background = "rgba(255,165,0,0.1)";
  });

  // 6. ステータス更新ボタン
  container.querySelector("#btn-update-status").addEventListener("click", async () => {
    if (!selectedRow) return;
    const comment = container.querySelector("#detail-comment").value;
    const newStatus = prompt("新しいステータスを入力 (未対応/対応中/解決済み/無視):", selectedRow.ステータス || selectedRow.status || '');
    if (!newStatus) return;

    const updated = await window.aivicApi.update(0, selectedRow.エラーログID || selectedRow.id, {
      ステータス: newStatus,
      対応コメント: comment,
      更新日時: new Date().toISOString()
    });

    if (updated) {
      alert("ステータスを更新しました");
      window.aivicApi.list(0).then(rows => {
        allRows = rows || [];
        renderRows(allRows);
        detailEmpty.style.display = "flex";
        detailPanel.style.display = "none";
      });
    }
  });

  // 7. 詳細パネル閉じるボタン
  container.querySelector("#btn-close-detail").addEventListener("click", () => {
    detailPanel.style.display = "none";
    detailEmpty.style.display = "flex";
    document.querySelectorAll("tbody tr").forEach(t => t.style.background = "");
    selectedRow = null;
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 0=エラーログ, 1=責任者マスタ, 2=エラー分類マスタ, 3=通知履歴
  const errorTableIndex = 0;
  const responsibleTableIndex = 1;
  const categoryTableIndex = 2;

  let allErrors = [];
  let selectedErrorId = null;

  // ===== 1. 再描画関数 =====
  function renderErrorRows(rows) {
    const tbody = container.querySelector("#error-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="background: rgba(0,0,0,0.2); height: 40px;"><td colspan="8" style="padding: 0.5rem; text-align: center; color: var(--text-muted);">エラーがありません</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map(r => {
      const priorityColor = r.重要度 === 'CRITICAL' ? '#ff6a00' : r.重要度 === 'WARNING' ? '#fbbf24' : '#9fb0d1';
      const statusBg = r.ステータス === '未対応' ? 'rgba(255,106,0,0.15)' : r.ステータス === '対応中' ? 'rgba(239,68,68,0.15)' : 'rgba(74,222,128,0.15)';
      const statusColor = r.ステータス === '未対応' ? '#ff6a00' : r.ステータス === '対応中' ? '#ef4444' : '#4ade80';

      return `
        <tr data-id="${r.id || ''}" style="border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer; transition: background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.05)'" onmouseout="this.style.background=''">
          <td style="padding: 0.5rem; color: var(--text); font-family: monospace; font-size: 0.8rem;">${(r.id || '').substring(0, 8)}</td>
          <td style="padding: 0.5rem; color: var(--text);">${r.受注番号 || '-'}</td>
          <td style="padding: 0.5rem; color: var(--text); font-size: 0.8rem;">${r.エラー分類 || '-'}</td>
          <td style="padding: 0.5rem; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 200px;" title="${r.エラーメッセージ || ''}">${r.エラーメッセージ || '-'}</td>
          <td style="padding: 0.5rem; color: ${priorityColor}; font-weight: 600;">${r.重要度 || '-'}</td>
          <td style="padding: 0.5rem; background: ${statusBg}; color: ${statusColor}; border-radius: 0.25rem; text-align: center; font-size: 0.8rem; font-weight: 600;">${r.ステータス || '-'}</td>
          <td style="padding: 0.5rem; color: var(--text-muted); font-size: 0.8rem;">${r.発生日時 ? new Date(r.発生日時).toLocaleString('ja-JP') : '-'}</td>
          <td style="padding: 0.5rem; text-align: center;">
            <button class="action-btn secondary edit-btn" data-id="${r.id || ''}" style="padding: 0.25rem 0.5rem; font-size: 0.75rem;">詳細</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // ===== 2. KPI 更新関数 =====
  function updateKpis(rows) {
    const pending = rows.filter(r => r.ステータス === '未対応').length;
    const inProgress = rows.filter(r => r.ステータス === '対応中').length;
    const resolved = rows.filter(r => r.ステータス === '解決済み').length;
    const today = rows.filter(r => {
      const d = new Date(r.発生日時);
      const now = new Date();
      return d.toDateString() === now.toDateString();
    }).length;

    container.querySelector('[data-testid="kpi-pending"]').textContent = pending;
    container.querySelector('[data-testid="kpi-in-progress"]').textContent = inProgress;
    container.querySelector('[data-testid="kpi-resolved"]').textContent = resolved;
    container.querySelector('[data-testid="kpi-today"]').textContent = today;
  }

  // ===== 3. フィルタ適用関数 =====
  function applyFilters() {
    const responsible = container.querySelector('[data-testid="filter-responsible"]').value;
    const category = container.querySelector('[data-testid="filter-category"]').value;
    const priority = container.querySelector('[data-testid="filter-priority"]').value;
    const status = container.querySelector('[data-testid="filter-status"]').value;
    const dateFrom = container.querySelector('[data-testid="filter-date-from"]').value;

    let filtered = allErrors.filter(r => {
      if (responsible && r.責任者 !== responsible) return false;
      if (category && r.エラー分類 !== category) return false;
      if (priority && r.重要度 !== priority) return false;
      if (status && r.ステータス !== status) return false;
      if (dateFrom) {
        const rDate = new Date(r.発生日時).toISOString().split('T')[0];
        if (rDate < dateFrom) return false;
      }
      return true;
    });

    renderErrorRows(filtered);
    updateKpis(filtered);
  }

  // ===== 4. 詳細パネル表示関数 =====
  function showDetailPanel(errorId) {
    const error = allErrors.find(e => e.id === errorId);
    if (!error) return;

    selectedErrorId = errorId;
    const panel = container.querySelector('#detail-panel');
    container.querySelector('[data-testid="detail-handler"]').value = error.対応者ID || '';
    container.querySelector('[data-testid="detail-status"]').value = error.ステータス === '未対応' ? 'pending' : error.ステータス === '対応中' ? 'in-progress' : 'resolved';
    container.querySelector('[data-testid="detail-comment"]').value = error.対応コメント || '';
    panel.style.display = 'block';
  }

  // ===== 5. 初期データ読み込み =====
  window.aivicApi.list(errorTableIndex).then(rows => {
    allErrors = rows || [];
    renderErrorRows(allErrors);
    updateKpis(allErrors);
  });

  // ===== 6. イベントリスナー登録 =====

  // 検索ボタン
  container.querySelector('[data-testid="search-button"]').addEventListener('click', applyFilters);

