  container.querySelector('[data-testid="close-detail"]').addEventListener('click', () => {
    container.querySelector('#detail-panel').style.display = 'none';
    selectedErrorId = null;
  });

  // 詳細パネル保存ボタン
  container.querySelector('[data-testid="save-detail-button"]').addEventListener('click', async () => {
    if (!selectedErrorId) return;

    const handler = container.querySelector('[data-testid="detail-handler"]').value;
    const statusMap = { 'pending': '未対応', 'in-progress': '対応中', 'resolved': '解決済み' };
    const status = statusMap[container.querySelector('[data-testid="detail-status"]').value] || '未対応';
    const comment = container.querySelector('[data-testid="detail-comment"]').value;

    const updated = await window.aivicApi.update(errorTableIndex, selectedErrorId, {
      対応者ID: handler,
      ステータス: status,
      対応コメント: comment
    });

    if (updated) {
      window.aivicApi.list(errorTableIndex).then(rows => {
        allErrors = rows || [];
        renderErrorRows(allErrors);
        updateKpis(allErrors);
        container.querySelector('#detail-panel').style.display = 'none';
        selectedErrorId = null;
      });
