      ステータス: '対応中',
      重要度: 'CRITICAL'
    });

    if (updated) {
      window.aivicApi.list(errorTableIndex).then(rows => {
        allErrors = rows || [];
        renderErrorRows(allErrors);
        updateKpis(allErrors);
        container.querySelector('#detail-panel').style.display = 'none';
        selectedErrorId = null;
      });
