  // 3. 検索・フィルター
  function applyFilters() {
    const dateVal = filterDate.value;
    const statusVal = filterStatus.value;
    const errorTypeVal = filterErrorType.value;
    const orderIdVal = filterOrderId.value.toLowerCase();

    const filtered = allRows.filter(r => {
      const execDate = r.実行開始日時 ? new Date(r.実行開始日時).toISOString().split('T')[0] : "";
      const matchDate = !dateVal || execDate === dateVal;
      const matchStatus = !statusVal || r.処理ステータス === statusVal;
      const matchErrorType = !errorTypeVal || (r.エラー種別 || "").includes(errorTypeVal);
      const matchOrderId = !orderIdVal || (r.受注データID || "").toLowerCase().includes(orderIdVal);

      return matchDate && matchStatus && matchErrorType && matchOrderId;
    });

    renderRows(filtered);
