    const headers = ["実行日時", "連携種別", "ステータス", "送信件数", "成功件数", "失敗件数", "エラーコード", "エラー詳細"];
    const rows = allRows.map(r => [
      r.実行開始日時 ? new Date(r.実行開始日時).toLocaleString('ja-JP') : "",
      r.連携種別 || "",
      r.処理ステータス || "",
      r.送信データ件数 || 0,
      r.成功件数 || 0,
      r.失敗件数 || 0,
      r.基幹システムレスポンスコード || "",
