function(container, apiUrl, tables) {
  // テーブルインデックスの特定
  const tableIndexMap = {};
  tables.forEach((t, idx) => {
    tableIndexMap[t.tableName] = idx;
  });

  const validationTbody = container.querySelector("#validation-tbody");
  const timelineContainer = container.querySelector("[data-testid='timeline-container']");
  const errorDetailPanel = container.querySelector("#error-detail-panel");
  const errorClassificationDiv = container.querySelector("[data-testid='error-classification']");

  // 1. バリデーション結果テーブルの再描画
  function renderValidationResults(rows) {
    validationTbody.innerHTML = rows.map(r => {
      const statusColor = r.検証ステータス === "成功" ? "#4ade80" : r.検証ステータス === "失敗" ? "#ff6a00" : "#fbbf24";
      return `
        <tr data-id="${r.バリデーション結果ID}" style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer;" class="validation-row">
          <td style="padding: 0.375rem; color: var(--text);">${r.受注データID ? r.受注データID.substring(0, 8) : "—"}</td>
          <td style="padding: 0.375rem; color: ${statusColor}; font-weight: 500;">${r.検証ステータス || "—"}</td>
          <td style="padding: 0.375rem; color: var(--text);">${r.エラーメッセージ ? "1" : "0"}</td>
        </tr>
      `;
    }).join("");
  }

  // 2. 連携履歴タイムラインの再描画
  function renderTimeline(rows) {
    timelineContainer.innerHTML = rows.slice(0, 8).map(r => {
      const statusColor = r.処理ステータス === "成功" ? "#4ade80" : r.処理ステータス === "失敗" ? "#ff6a00" : "#fbbf24";
      const date = r.実行開始日時 ? new Date(r.実行開始日時).toLocaleString("ja-JP", { month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" }) : "—";
      return `
        <div style="display: flex; gap: 0.5rem; padding: 0.5rem; border-left: 3px solid ${statusColor}; background: rgba(0,0,0,0.15); border-radius: 0.25rem;">
          <div style="flex: 1;">
            <div style="font-size: 0.7rem; color: var(--text-muted);">${date}</div>
            <div style="font-size: 0.75rem; color: var(--text); font-weight: 500;">${r.連携種別 || "—"}</div>
            <div style="font-size: 0.7rem; color: var(--text-muted);">成功: ${r.成功件数 || 0} / 失敗: ${r.失敗件数 || 0}</div>
          </div>
          <div style="font-size: 0.75rem; color: ${statusColor}; font-weight: 600; text-align: right;">${r.処理ステータス || "—"}</div>
        </div>
      `;
    }).join("");
  }

  // 3. エラー分類集計の再描画
  function renderErrorClassification(rows) {
    const errorCounts = {};
    rows.forEach(r => {
      const code = r.エラーコード || "その他";
      errorCounts[code] = (errorCounts[code] || 0) + 1;
    });
    errorClassificationDiv.innerHTML = Object.entries(errorCounts).slice(0, 6).map(([code, count]) => `
      <div style="padding: 0.375rem; background: rgba(0,0,0,0.15); border-radius: 0.25rem;">
        <div style="font-size: 0.65rem; color: var(--text-muted);">${code}</div>
        <div style="font-size: 0.85rem; font-weight: 600; color: #ff6a00;">${count}件</div>
      </div>
    `).join("");
  }

  // 4. KPI の更新
  function updateKPIs(validationRows, integrationRows) {
    const totalCount = integrationRows.length;
    const successCount = integrationRows.filter(r => r.処理ステータス === "成功").length;
    const successRate = totalCount > 0 ? Math.round((successCount / totalCount) * 100) : 0;
    const errorCount = validationRows.filter(r => r.検証ステータス === "失敗").length;
    const pendingCount = integrationRows.filter(r => r.処理ステータス === "処理中").length;

    container.querySelector("[data-testid='kpi-total-count']").textContent = totalCount;
    container.querySelector("[data-testid='kpi-success-rate']").textContent = successRate + "%";
    container.querySelector("[data-testid='kpi-error-count']").textContent = errorCount;
    container.querySelector("[data-testid='kpi-pending-count']").textContent = pendingCount;
  }

  // 5. 初期データ読み込み
  async function loadInitialData() {
    try {
      const validationIdx = tableIndexMap["バリデーション結果"];
      const integrationIdx = tableIndexMap["基幹システム連携履歴"];
      const errorIdx = tableIndexMap["エラーログ"];

      let validationRows = [];
      let integrationRows = [];
      let errorRows = [];

      if (validationIdx !== undefined) {
        validationRows = await window.aivicApi.list(validationIdx) || tables[validationIdx]?.records || [];
      }
      if (integrationIdx !== undefined) {
        integrationRows = await window.aivicApi.list(integrationIdx) || tables[integrationIdx]?.records || [];
      }
      if (errorIdx !== undefined) {
        errorRows = await window.aivicApi.list(errorIdx) || tables[errorIdx]?.records || [];
      }

      renderValidationResults(validationRows);
      renderTimeline(integrationRows);
      renderErrorClassification(errorRows);
      updateKPIs(validationRows, integrationRows);
    } catch (e) {
      console.error("初期データ読み込みエラー:", e);
    }
  }

  // 6. 検索ボタンのイベントリスナー
  container.querySelector("[data-testid='search-button']").addEventListener("click", async () => {
    const datetime = container.querySelector("[data-testid='filter-datetime']").value;
    const status = container.querySelector("[data-testid='filter-status']").value;
    const channel = container.querySelector("[data-testid='filter-channel']").value;

    try {
      const integrationIdx = tableIndexMap["基幹システム連携履歴"];
      if (integrationIdx === undefined) return;

      let rows = await window.aivicApi.list(integrationIdx) || tables[integrationIdx]?.records || [];

      if (datetime) {
        const dt = new Date(datetime);
        rows = rows.filter(r => r.実行開始日時 && new Date(r.実行開始日時) >= dt);
      }
      if (status) {
        rows = rows.filter(r => r.処理ステータス === status);
      }
      if (channel) {
        rows = rows.filter(r => r.連携種別 && r.連携種別.includes(channel));
      }

      renderTimeline(rows);
      updateKPIs([], rows);
    } catch (e) {
      console.error("検索エラー:", e);
    }
  });

  // 7. CSVエクスポートボタン
  container.querySelector("[data-testid='export-button']").addEventListener("click", async () => {
    try {
      const integrationIdx = tableIndexMap["基幹システム連携履歴"];
      if (integrationIdx === undefined) return;

      const rows = await window.aivicApi.list(integrationIdx) || tables[integrationIdx]?.records || [];
      const headers = ["連携履歴ID", "連携種別", "処理ステータス", "成功件数", "失敗件数", "実行開始日時"];
      const csv = "\uFEFF" + headers.join(",") + "\n" + rows.map(r =>
        [r.連携履歴ID, r.連携種別, r.処理ステータス, r.成功件数, r.失敗件数, r.実行開始日時].map(v => `"${(v || "").toString().replace(/"/g, '""')}"`).join(",")
      ).join("\n");

      const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = "連携結果_" + new Date().toISOString().split("T")[0] + ".csv";
      link.click();
    } catch (e) {
      console.error("エクスポートエラー:", e);
    }
  });

  // 8. エラー詳細パネルの展開/折畳
  container.querySelector("[data-testid='toggle-error-detail']").addEventListener("click", () => {
    const isHidden = errorDetailPanel.style.display === "none";
    errorDetailPanel.style.display = isHidden ? "block" : "none";
    container.querySelector("[data-testid='toggle-error-detail']").textContent = isHidden ? "折畳" : "展開";
  });

  // 9. バリデーション行クリックでエラー詳細を表示
  container.addEventListener("click", async (e) => {
    const row = e.target.closest(".validation-row");
    if (row) {
      const id = row.dataset.id;
      try {
        const errorIdx = tableIndexMap["エラーログ"];
        if (errorIdx === undefined) return;

        const errorRows = await window.aivicApi.list(errorIdx) || tables[errorIdx]?.records || [];
        const relatedErrors = errorRows.filter(er => er.バリデーション結果ID === id);

        if (relatedErrors.length > 0) {
          errorDetailPanel.innerHTML = relatedErrors.map(err => `
            <div style="padding: 0.5rem; border-bottom: 1px solid rgba(255,255,255,0.08);">
              <div style="font-size: 0.7rem; color: #ff6a00; font-weight: 600;">${err.エラーコード || "—"}</div>
              <div style="font-size: 0.75rem; color: var(--text);">${err.エラーメッセージ || "—"}</div>
              <div style="font-size: 0.65rem; color: var(--text-muted);">${err.重要度 || "—"} | ${err.発生モジュール || "—"}</div>
            </div>
          `).join("");
          errorDetailPanel.style.display = "block";
        }
      } catch (e) {
        console.error("エラー詳細取得エラー:", e);
      }
    }
  });

  // 10. エラーログ検索
  container.querySelector("[data-testid='search-error-log-button']").addEventListener("click", async () => {
    const keyword = container.querySelector("[data-testid='error-log-search']").value.toLowerCase();
    try {
      const errorIdx = tableIndexMap["エラーログ"];
      if (errorIdx === undefined) return;

      const rows = await window.aivicApi.list(errorIdx) || tables[errorIdx]?.records || [];
      const filtered = rows.filter(r =>
        (r.エラーコード && r.エラーコード.toLowerCase().includes(keyword)) ||
        (r.エラーメッセージ && r.エラーメッセージ.toLowerCase().includes(keyword))
      );

      renderErrorClassification(filtered);
    } catch (e) {
      console.error("エラーログ検索エラー:", e);
    }
  });

  // 初期化実行
  loadInitialData();
}

function(container, apiUrl, tables) {
  const detailPanel = container.querySelector("#detail-panel");
  const detailTemplate = container.querySelector("#detail-template");
  const orderTbody = container.querySelector("#order-tbody");
  let allOrders = [];
  let selectedOrderId = null;

  // 1. 再描画関数
  function renderOrders(orders) {
    if (!orders || orders.length === 0) {
      orderTbody.innerHTML = '<tr style="background: rgba(0,0,0,0.2); color: var(--text-muted);"><td colspan="5" style="padding: 1rem; text-align: center;">該当する受注がありません</td></tr>';
      return;
    }
    orderTbody.innerHTML = orders.map(order => {
      const errorCount = Math.floor(Math.random() * 5); // ダミー（実際はバリデーション結果から取得）
      const validationStatus = errorCount === 0 ? '成功' : (errorCount <= 2 ? '警告' : '失敗');
      const statusColor = validationStatus === '成功' ? '#4ade80' : (validationStatus === '警告' ? '#f59e0b' : '#ef4444');
      return `
        <tr data-id="${order.id}" style="border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer; transition: background 0.15s;" onmouseover="this.style.background='rgba(212,175,55,0.1)'" onmouseout="this.style.background=''">
          <td style="padding: 0.5rem; color: var(--text);">${order.受注番号 || '-'}</td>
          <td style="padding: 0.5rem; color: var(--text-muted); font-size: 0.8rem;">${order.顧客ID ? order.顧客ID.substring(0, 8) + '...' : '-'}</td>
          <td style="padding: 0.5rem; text-align: right; color: var(--text); font-weight: 500;">¥${(order.受注金額 || 0).toLocaleString()}</td>
          <td style="padding: 0.5rem; text-align: center;"><span style="display: inline-block; padding: 0.25rem 0.5rem; border-radius: 0.25rem; background: ${statusColor}20; color: ${statusColor}; font-size: 0.75rem; font-weight: 600;">${validationStatus}</span></td>
          <td style="padding: 0.5rem; text-align: center; color: var(--text);">${errorCount}</td>
        </tr>
      `;
    }).join("");

    // 行クリックイベント
    orderTbody.querySelectorAll("tr[data-id]").forEach(row => {
      row.addEventListener("click", () => {
        orderTbody.querySelectorAll("tr[data-id]").forEach(r => r.style.background = "");
        row.style.background = "rgba(212,175,55,0.15)";
        selectedOrderId = row.dataset.id;
        const order = orders.find(o => o.id === selectedOrderId);
        showDetailPanel(order);
      });
    });
  }

  // 2. 詳細パネル表示
  function showDetailPanel(order) {
    const clone = detailTemplate.content.cloneNode(true);

    // 受注情報を入力
    clone.querySelector("#detail-order-id").textContent = order.id || '-';
    clone.querySelector("#detail-order-number").textContent = order.受注番号 || '-';
    clone.querySelector("#detail-order-date").textContent = order.受注日 ? new Date(order.受注日).toLocaleDateString('ja-JP') : '-';
    clone.querySelector("#detail-delivery-date").textContent = order.納期 ? new Date(order.納期).toLocaleDateString('ja-JP') : '-';
    clone.querySelector("#detail-amount").textContent = `¥${(order.受注金額 || 0).toLocaleString()}`;

    // バリデーション結果（ダミー）
    const validationResults = [
      { rule: '必須項目チェック', status: '成功', message: 'すべての必須項目が入力されています' },
      { rule: '金額範囲チェック', status: '成功', message: '受注金額が有効範囲内です' },
      { rule: '顧客与信チェック', status: '警告', message: '顧客の与信限度額に接近しています' }
    ];
    clone.querySelector("#detail-validation-results").innerHTML = validationResults.map(v => {
      const color = v.status === '成功' ? '#4ade80' : (v.status === '警告' ? '#f59e0b' : '#ef4444');
      return `<div style="padding: 0.25rem; border-left: 2px solid ${color}; padding-left: 0.5rem;"><strong>${v.rule}</strong>: <span style="color: ${color};">${v.status}</span> - ${v.message}</div>`;
    }).join("");

    // エラーログ（ダミー）
    const errorLogs = [
      { code: 'VAL_001', message: '顧客与信限度額チェック: 現在の与信使用率 85%', severity: 'WARNING' },
      { code: 'VAL_002', message: '納期が過去日付になっていないか確認', severity: 'INFO' }
    ];
    clone.querySelector("#detail-error-logs").innerHTML = errorLogs.length > 0 ? errorLogs.map(log => {
      const color = log.severity === 'ERROR' ? '#ef4444' : (log.severity === 'WARNING' ? '#f59e0b' : '#3b82f6');
      return `<div style="padding: 0.25rem; border-left: 2px solid ${color}; padding-left: 0.5rem;"><strong style="color: ${color};">${log.code}</strong>: ${log.message}</div>`;
    }).join("") : '<div style="color: var(--text-muted);">エラーなし</div>';

    detailPanel.innerHTML = "";
    detailPanel.appendChild(clone);
  }

  // 3. 初期データ読み込み
  async function loadOrders() {
    const rows = await window.aivicApi.list(0);
    allOrders = rows || tables[0].records || [];
    renderOrders(allOrders);
  }

  // 4. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", () => {
    const orderNumber = container.querySelector("#filter-order-number").value.toLowerCase();
    const customerId = container.querySelector("#filter-customer-id").value.toLowerCase();
    const validationStatus = container.querySelector("#filter-validation-status").value;
    const errorCategory = container.querySelector("#filter-error-category").value;

    const filtered = allOrders.filter(order => {
      const matchOrder = !orderNumber || (order.受注番号 || "").toLowerCase().includes(orderNumber);
      const matchCustomer = !customerId || (order.顧客ID || "").toLowerCase().includes(customerId);
      return matchOrder && matchCustomer;
    });

    renderOrders(filtered);
  });

  // 5. 更新ボタン
  container.querySelector("#btn-refresh").addEventListener("click", loadOrders);

  // 6. 承認ボタン
  container.querySelector("#btn-approve").addEventListener("click", async () => {
    if (!selectedOrderId) {
      alert("受注を選択してください");
      return;
    }
    const responsibleUser = container.querySelector("#detail-responsible-user").value;
    if (!responsibleUser) {
      alert("責任者を選択してください");
      return;
    }
    if (confirm("この受注を承認しますか？")) {
      // 実装: 承認処理（API呼び出し）
      alert("承認しました");
      loadOrders();
    }
  });

  // 7. 却下ボタン
  container.querySelector("#btn-reject").addEventListener("click", () => {
    if (!selectedOrderId) {
      alert("受注を選択してください");
      return;
    }
    const instruction = container.querySelector("#detail-correction-instruction").value;
    if (!instruction) {
      alert("修正指示を入力してください");
      return;
    }
    if (confirm("この受注を却下しますか？")) {
      // 実装: 却下処理（API呼び出し）
      alert("却下しました");
      loadOrders();
    }
  });

  // 8. 通知送信ボタン
  container.querySelector("#btn-send-notification").addEventListener("click", async () => {
    if (!selectedOrderId) {
      alert("受注を選択してください");
      return;
    }
    const responsibleUser = container.querySelector("#detail-responsible-user").value;
    if (!responsibleUser) {
      alert("責任者を選択してください");
      return;
    }
    if (confirm("責任者に通知を送信しますか？")) {
      // 実装: 通知送信処理（API呼び出し）
      alert("通知を送信しました");
    }
  });

  // 初期化
  loadOrders();
}
